package com.acme.jobs.matching;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Map;

/**
 * Scores how well a candidate's skills match a posting's requirements.
 */
public class SkillMatchScorer {

    private final PostingRepository postings;

    public SkillMatchScorer(PostingRepository postings) {
        this.postings = postings;
    }

    public BigDecimal score(String postingId, CandidateProfile candidate) {
        Posting p = postings.require(postingId);
        Map<String, BigDecimal> weights = p.getSkillWeights();
        BigDecimal totalWeight = weights.values().stream().reduce(BigDecimal.ZERO, BigDecimal::add);
        if (totalWeight.signum() == 0) {
            return BigDecimal.ZERO;
        }
        BigDecimal matched = BigDecimal.ZERO;
        for (Map.Entry<String, BigDecimal> e : weights.entrySet()) {
            if (candidate.getSkills().contains(e.getKey())) {
                matched = matched.add(e.getValue());
            }
        }
        return matched.multiply(BigDecimal.valueOf(100))
            .divide(totalWeight, 2, RoundingMode.HALF_UP);
    }
}

