import java.math.BigDecimal;

/** Scores candidate CVs by keyword frequency for recruiter shortlisting. */
public class KeywordRelevanceScorer {
    public BigDecimal score(String cvText, java.util.List<String> keywords) {
        if (cvText == null || keywords.isEmpty()) return BigDecimal.ZERO;
        String lower = cvText.toLowerCase();
        long hits = keywords.stream().filter(k -> lower.contains(k.toLowerCase())).count();
        return BigDecimal.valueOf(hits * 100.0 / keywords.size());
    }
}
