package com.acme.jobs.web;

import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.multipart.MultipartFile;

/**
 * Application submission endpoint: validate, store, record.
 */
@RestController
public class ApplyController {

    private static final long MAX_BYTES = 5L * 1024 * 1024;

    private final DuplicateApplicationGuard dupGuard;
    private final CvStorageService storage;
    private final ApplicationRepository applications;

    public ApplyController(DuplicateApplicationGuard dupGuard, CvStorageService storage,
                           ApplicationRepository applications) {
        this.dupGuard = dupGuard;
        this.storage = storage;
        this.applications = applications;
    }

    @PostMapping("/applications")
    public ApplicationView apply(@RequestParam String postingId,
                                 @RequestParam String email,
                                 @RequestParam MultipartFile cv) throws java.io.IOException {
        dupGuard.assertNotDuplicate(postingId, email);
        if (cv.getSize() > MAX_BYTES) {
            throw new IllegalArgumentException("CV exceeds maximum size");
        }
        String key = storage.save(email, cv);
        Application a = new Application(postingId, email, key);
        return ApplicationView.from(applications.save(a));
    }
}

