package com.acme.jobs.postings;

import java.time.LocalDate;
import java.util.List;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

/**
 * Publishes a job posting after validating required fields.
 */
@RestController
public class PublishPostingController {

    private final PostingRepository postings;
    private final NotificationGateway notifier;

    public PublishPostingController(PostingRepository postings, NotificationGateway notifier) {
        this.postings = postings;
        this.notifier = notifier;
    }

    @PostMapping("/postings")
    public PostingView publish(@RequestBody PublishPostingRequest req) {
        if (req.getTitle() == null || req.getTitle().isBlank()) {
            throw new IllegalArgumentException("Title is required");
        }
        if (req.getClosesOn() == null || req.getClosesOn().isBefore(LocalDate.now())) {
            throw new IllegalArgumentException("Closing date must be in the future");
        }
        if (req.getRequiredSkills() == null || req.getRequiredSkills().isEmpty()) {
            throw new IllegalArgumentException("At least one required skill must be specified");
        }
        Posting p = new Posting(req.getRecruiterId(), req.getTitle(), req.getDescription(), req.getRequiredSkills(), req.getClosesOn());
        p.setStatus(PostingStatus.OPEN);
        Posting saved = postings.save(p);
        notifier.publish("postings", "New posting: " + saved.getTitle());
        return PostingView.from(saved);
    }
}

