package com.acme.jobs.audit;

import java.time.Instant;
import javax.persistence.EntityManager;
import javax.persistence.EntityTransaction;

/**
 * Appends an immutable entry on each application status change.
 */
public class ApplicationStatusAuditor {

    private final EntityManager em;

    public ApplicationStatusAuditor(EntityManager em) {
        this.em = em;
    }

    public void record(String applicationId, String oldStatus, String newStatus, String actorId) {
        EntityTransaction tx = em.getTransaction();
        tx.begin();
        try {
            ApplicationStatusEntry e = new ApplicationStatusEntry();
            e.setApplicationId(applicationId);
            e.setOldStatus(oldStatus);
            e.setNewStatus(newStatus);
            e.setActorId(actorId);
            e.setOccurredAt(Instant.now());
            em.persist(e);
            tx.commit();
        } catch (RuntimeException ex) {
            tx.rollback();
            throw ex;
        }
    }
}

