/* weekly_digest.c - send weekly application-status digest per candidate */
#include <stdio.h>
#include "jobs_db.h"

int run_weekly_digest(const char *from_date, const char *to_date) {
    db_cursor_t *cur = NULL;
    if (db_open_changed_applications_cursor(&cur, from_date, to_date) != DB_OK) return -1;

    char current_email[256] = {0};
    int sent = 0;
    change_row_t row;
    while (db_change_cursor_next(cur, &row) == DB_OK) {
        if (strcmp(current_email, row.candidate_email) != 0) {
            if (current_email[0] != 0) sent++;
            snprintf(current_email, sizeof(current_email), "%s", row.candidate_email);
        }
        db_queue_digest_line(row.candidate_email, row.posting_title, row.new_status);
    }
    db_close_cursor(cur);

    if (current_email[0] != 0) sent++;
    return sent;
}

